node -e "
const fs = require('fs');
const buf = fs.readFileSync('/workspace/world.db');
const text = buf.toString('latin1');
// Find cart_items table
const match = text.match(/CREATE TABLE cart_items[^)]+\)/i);
if (match) console.log(match[0]);
// Find shipping_options
const match2 = text.match(/CREATE TABLE shipping[^)]+\)/i);
if (match2) console.log(match2[0]);
// Find all table names
const tables = text.match(/CREATE TABLE (\w+)/gi);
if (tables) console.log('\nAll tables:', tables.map(t => t.replace('CREATE TABLE ', '')).join(', '));
"

